# owner: platform
"""Snapping clock times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def check_step(step: int) -> None:
    """Step must be a positive divisor of sixty."""
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour evenly: {step!r}"
        )


def snap_minute(minute: int, step: int) -> int:
    """Nearest multiple of step. Exact halves round up."""
    return (minute + step // 2) // step * step


def round_span(span: Span, step: int) -> Span:
    """Snap both ends. A collapsed span is an error."""
    check_step(step)
    return Span(
        snap_minute(span.start, step),
        snap_minute(span.end, step)
    )


def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    hours, extra = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {extra}m)"


def label_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """One label per span, in order, after rounding."""
    check_step(step)
    rounded = [round_span(span, step) for span in spans]
    return [span_label(span) for span in rounded]

