# owner: platform
import unittest

from hourglass.rounding import (
    label_spans,
    round_span,
    snap_minute
)
from hourglass.parsing import parse_span
from hourglass.models import Span


class SnapTests(unittest.TestCase):
    def test_rounds_down_below_half(self):
        self.assertEqual(snap_minute(536, 15), 540)
        self.assertEqual(snap_minute(541, 15), 540)

    def test_exact_half_rounds_up(self):
        self.assertEqual(snap_minute(15, 30), 30)

    def test_step_of_one_changes_nothing(self):
        self.assertEqual(snap_minute(547, 1), 547)


class RoundSpanTests(unittest.TestCase):
    def test_both_ends_move(self):
        result = round_span(parse_span("09:04-17:10"), 15)
        self.assertEqual(result, parse_span("09:00-17:15"))

    def test_collapsed_span_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 545), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:16")]
        self.assertEqual(
            label_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_order_is_kept(self):
        spans = [
            parse_span("13:00-14:00"),
            parse_span("08:00-09:30")
        ]
        self.assertEqual(
            label_spans(spans, 30),
            ["13:00-14:00 (1h 0m)", "08:00-09:30 (1h 30m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_spans([], 15), [])


class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        spans = [Span(60, 120)]
        for step in (0, -15, 7, 45, 90, 2.5):
            with self.assertRaises(ValueError):
                label_spans(spans, step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            label_spans([], 0)
